# Simpler approach: process main AND anti diagonals
def process_diagonals(grid, key_func):
    """key_func takes (r,c) and returns a hashable key identifying which diagonal"""
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]
    diags = defaultdict(list)
    for r in range(len(result)):
        for c in range(len(result[0])):
            key = key_func(r,c)
            diags[key].append((r,c))

    filled = set()
    for key, cells in diags.items():
        if len(cells) < 2:
            continue
        vals = [result[r][c] for r,c in cells if result[r][c] != 0]
        if len(set(vals)) == 1:
            fill_val = vals[0]
            for r,c in cells:
                if result[r][c] == 0:
                    result[r][c] = fill_val
                    filled.add((r,c))
    return result, filled

def apply_all_diagonals(grid):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    def make_key(type_, offset):
        def key_func(r,c):
            return (type_, offset + (r if type_=='main' else c))
        return key_func

    # Main diagonals: same value on (r-c)=constant
    main_result = process_diagonals(result, lambda rc: (rc[0]-rc[1], rc[0]+rc[1]))  # hacky

    # Let me just do it simply and separately
    result_main, filled_main = process_diagonals(result, lambda rc: rc[0]-rc[1])
    result_anti, filled_anti = process_diagonals(result_main.copy(), lambda rc: rc[0]+rc[1])

    return result_anti, filled_main | filled_anti

