from collections import defaultdict, Counter

def fill_by_vote(grid):
    """For each zero, fill with majority vote from all diagonals passing through it"""
    n = len(grid)
    m = len(grid[0])
    result = [[grid[r][c] for c in range(m)] for r in range(n)]

    # Precompute diagonals: map from (type, index) to list of cells
    diags = defaultdict(list)
    for r in range(n):
        for c in range(m):
            diags[('main', r-c)].append((r,c))
            diags[('anti', r+c)].append((r,c))

    # Process each zero cell
    for r in range(n):
        for c in range(m):
            if result[r][c] != 0:
                continue

            # Collect all non-zero values from all diagonals passing through (r,c)
            all_vals = []
            diag_keys = [('main', r-c), ('anti', r+c)]
            for typ, idx in diag_keys:
                for rr, cc in diags[(typ, idx)]:
                    if result[rr][cc] != 0:
                        all_vals.append(result[rr][cc])

            if all_vals:
                counter = Counter(all_vals)
                fill_val = counter.most_common(1)[0][0]
                result[r][c] = fill_val

    return result

