        changed = False
        for r in range(n):
            for c in range(m):
                if result[r][c] != 0:
                    continue

                # Collect ALL non-zeros from both diagonals
                all_vals = []
                diag_keys = [('main', r-c), ('anti', r+c)]
                for typ, idx in diag_keys:
                    for rr, cc in diags[(typ, idx)]:
