from collections import Counter, defaultdict

def hypothesize_fill_most_common(grid):
    result = [[v for v in row] for row in grid]

    n, m = len(result), len(result[0])
    diags_main = defaultdict(list)
    diags_anti = defaultdict(list)
    for r in range(n):
        for c in range(m):
            diags_main[r-c].append((r,c))
            diags_anti[r+c].append((r,c))

    # Precompute line values
    def get_line_cells(typ, idx):
        if typ == 'row':
            return [(r, c, result[r][c]) for c in range(m)]
        elif typ == 'col':
            return [(r, c, result[r][c]) for r in range(n)]
        elif typ == 'main':
            return list(diags_main[idx])
        elif typ == 'anti':
            return list(diags_anti[idx])
        return []

    changed = True
    iterations = 0
    while changed:
        changed = False
        iterations += 1
        if iterations > 100:
            break

        for typ in ['row', 'col', 'main', 'anti']:
            if typ == 'row':
                indices = range(n)
            elif typ == 'col':
                indices = range(m)
            else:
                indices = [idx for idx in (diags_main if typ == 'main' else diags_anti)]

            for idx in indices:
                cells = get_line_cells(typ, idx)
                vals = [v for _,_,v in cells]
                nz_vals = [v for v in vals if v != 0]

                if not nz_vals:
                    continue

                counter = Counter(nz_vals)
                fill_val = counter.most_common(1)[0][0]

                for rr, cc, val in cells:
                    if val == 0:
                        old_val = val
                        result[rr][cc] = fill_val
                        changed = True

    return result

