def fill_from_any_line(grid):
    """Fill every 0 with the first non-zero value found on any of its lines"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    # Precompute main and anti diagonal indices
    diags_main = {}
    diags_anti = {}
    for r in range(n):
        for c in range(m):
            d = r - c
            s = r + c
            if d not in diags_main: diags_main[d] = []
            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    changed = True
    iterations = 0
    while changed and iterations < 1000:
        changed = False
        iterations += 1

        # Fill by rows
        for r in range(n):
            nz_values = [result[r][c] for c in range(m) if result[r][c] != 0]
            if nz_values:
                val = nz_values[0]
                for c in range(m):
                    if result[r][c] == 0:
                        result[r][c] = val
                        changed = True

        # Fill by columns
        for c in range(m):
            nz_values = [result[r][c] for r in range(n) if result[r][c] != 0]
            if nz_values:
                val = nz_values[0]
                for r in range(n):
                    if result[r][c] == 0:
                        result[r][c] = val
                        changed = True

        # Fill by main diagonals
        for d_cells in diags_main.values():
            nz_list = []
            for rr, cc in d_cells:
                val = result[rr][cc]
                if val != 0:
                    nz_list.append(val)
            if nz_list:
                val = nz_list[0]
                for rr, cc in d_cells:
                    if result[rr][cc] == 0:
                        result[rr][cc] = val
                        changed = True

        # Fill by anti diagonals
        for s_cells in diags_anti.values():
            nz_list = []
            for rr, cc in s_cells:
                val = result[rr][cc]
                if val != 0:
                    nz_list.append(val)
            if nz_list:
                val = nz_list[0]
                for rr, cc in s_cells:
                    if result[rr][cc] == 0:
                        result[rr][cc] = val
                        changed = True

    return result

