import json
from collections import Counter

def fill_most_common(grid):
    """Fill zeros with MOST COMMON non-zero value across row/col/diag"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    changed = True
    while changed:
        changed = False

        # Rows
        for r in range(n):
            nz_vals = [result[r][c] for c in range(m) if result[r][c] != 0]
            if nz_vals:
                # Get mode (most common)
                counts = Counter(nz_vals).most_common(1)
                if counts:
                    val = counts[0][0]
                    count = counts[0][1]
                    total_zeros = sum(1 for v in result[r] if v == 0)
                    fill_ratio = count / (count + total_zeros)

                    # Fill if majority (>50%)
                    if fill_ratio > 0.5:
                        for c in range(m):
                            if result[r][c] == 0:
                                result[r][c] = val
                                changed = True

        # Columns
        for c in range(m):
            nz_vals = [result[r][c] for r in range(n) if result[r][c] != 0]
            if nz_vals:
                counts = Counter(nz_vals).most_common(1)
                if counts:
                    val = counts[0][0]
                    count = counts[0][1]
                    total_zeros = sum(1 for v in [result[r][c] for r in range(n)] if v == 0)
                    fill_ratio = count / (count + total_zeros)

                    if fill_ratio > 0.5:
                        for r in range(n):
                            if result[r][c] == 0:
                                result[r][c] = val
                                changed = True

        # Main diagonals
        diags_main = {}
        for r in range(n):
            for c in range(m):
                d = r - c
                if d not in diags_main:
                    diags_main[d] = []
                diags_main[d].append((r,c))

        for d_cells in diags_main.values():
            nz_vals = [result[r][c] for r,c in d_cells if result[r][c] != 0]
            if nz_vals:
                counts = Counter(nz_vals).most_common(1)
                if counts:
                    val = counts[0][0]
                    count = counts[0][1]
                    total_zeros = sum(1 for r,c in d_cells if result[r][c] == 0)
                    fill_ratio = count / (count + total_zeros)

                    if fill_ratio > 0.5:
                        for r,c in d_cells:
                            if result[r][c] == 0:
                                result[r][c] = val
                                changed = True

    return result

