            if d not in diags_main: diags_main[d] = []
            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    changed = True
    while changed:
        changed = False

        # Compute all fills FIRST based on current result state
        pending_fills = set()  # (r,c) coordinates to fill

        # Rows
        for r in range(n):
            nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for c in range(m):
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        # Cols
        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r in range(n):
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        # Main diags
        for cells in diags_main.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        # Anti diags
        for cells in diags_anti.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        # Apply all pending fills
        for r, c, val in pending_fills:
            result[r][c] = val
            changed = True

    return result

