    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    # First pass: fill rows with consistent values
    for r in range(n):
        nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
        if len(nz_vals) == 1:
            val = list(nz_vals)[0]
            for c in range(m):
                if result[r][c] == 0:
                    result[r][c] = val

    # Second pass: now fill columns
    changed = True
    while changed:
        changed = False

        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r in range(n):
                    if result[r][c] == 0:
                        result[r][c] = val
                        changed = True

    return result

