def solve_propagate_from_bands(grid):
    """Fill cells by propagating from complete bands in all directions"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    # Find all "complete" lines (rows, cols, diags) with single unique value
    # and use those to fill intersecting cells

    diags_main = {}
    diags_anti = {}
    for r in range(n):
        for c in range(m):
            d = r - c
            s = r + c
            if d not in diags_main: diags_main[d] = []
            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    changed = True
    while changed:
        changed = False

        # First find ALL constraints that are satisfied (single unique value lines)
        row_constraints = {}  # row -> val
        col_constraints = {}  # col -> val
        diag_constraints = {}  # diag -> val
        anti_diag_constraints = {}  # anti_diag -> val

        for r in range(n):
            nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
            if len(nz_vals) == 1:
                row_constraints[r] = list(nz_vals)[0]

        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                col_constraints[c] = list(nz_vals)[0]

        for d_cells in diags_main.values():
            nz_vals = {result[r][c] for r,c in d_cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                diag_constraints[r-c] = list(nz_vals)[0]

        for s_cells in diags_anti.values():
            nz_vals = {result[r][c] for r,c in s_cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                anti_diag_constraints[r+c] = list(nz_vals)[0]

        # Now apply ALL satisfying constraints
        for r in range(n):
            for c in range(m):
                if result[r][c] == 0:
                    vals_to_consider = []

                    if r in row_constraints:
                        vals_to_consider.append(('row', row_constraints[r]))
                    if c in col_constraints:
                        vals_to_consider.append(('col', col_constraints[c]))
                    if (r-c) in diag_constraints:
                        vals_to_consider.append(('diag', diag_constraints[r-c]))
                    if (r+c) in anti_diag_constraints:
                        vals_to_consider.append(('anti', anti_diag_constraints[r+c]))

                    if vals_to_consider:
                        # If all agree, fill
                        vals = set(v for _, v in vals_to_consider)
                        if len(vals) == 1:
                            val = list(vals)[0]
                            result[r][c] = val
                            changed = True

    return result

