def solve_from_original_constraints(grid):
    """Only fill cells that are justified by ORIGINAL grid's constraints"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    diags_main = {}
    diags_anti = {}
    orig_grid = [row[:] for row in grid]
    for r in range(n):
        for c in range(m):
            d = r - c
            s = r + c
            if d not in diags_main: diags_main[d] = []
            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    # Compute all constraint values from ORIGINAL grid
    row_vals = {}
    col_vals = {}
    diag_vals = {}
    anti_diag_vals = {}

    for r in range(n):
        nz = set(orig_grid[r][c] for c in range(m) if orig_grid[r][c] != 0)
        if len(nz) == 1:
            row_vals[r] = list(nz)[0]

    for c in range(m):
        nz = set(orig_grid[r][c] for r in range(n) if orig_grid[r][c] != 0)
        if len(nz) == 1:
            col_vals[c] = list(nz)[0]

    for d_cells in diags_main.values():
        nz = {orig_grid[r][c] for r,c in d_cells if orig_grid[r][c] != 0}
        if len(nz) == 1:
            diag_vals[r-c] = list(nz)[0]

    for s_cells in diags_anti.values():
        nz = {orig_grid[r][c] for r,c in s_cells if orig_grid[r][c] != 0}
        if len(nz) == 1:
            anti_diag_vals[r+c] = list(nz)[0]

    # For each empty cell, collect ALL constraining lines and check consistency
    for r in range(n):
        for c in range(m):
            if result[r][c] != 0:
                continue

            vals = set()
            if r in row_vals:
                vals.add(row_vals[r])
            if c in col_vals:
                vals.add(col_vals[c])
            if (r-c) in diag_vals:
                vals.add(diag_vals[r-c])
            if (r+c) in anti_diag_vals:
                vals.add(anti_diag_vals[r+c])

            # If multiple constraints point to different values, don't fill
            # If all agree on one value, fill it
            if len(vals) == 1:
                val = list(vals)[0]
                result[r][c] = val

    return result

