            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    changed = True
    while changed:
        changed = False

        pending_fills = set()

        # Compute all potential fills based on CURRENT result state
        for r in range(n):
            nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for c in range(m):
                    if result[r][c] == 0:
