        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r in range(n):
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        for cells in diags_main.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        for cells in diags_anti.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

