    filled = set()

    for r in range(n):
        nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
        if len(nz_vals) == 1:
            val = list(nz_vals)[0]
            for c in range(m):
                if result[r][c] != 0:
                    filled.add((r, c))

    for c in range(m):
        nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
        if len(nz_vals) == 1:
            val = list(nz_vals)[0]
            for r in range(n):
                if result[r][c] != 0:
                    filled.add((r, c))

    for r in range(n):
        for c in range(m):
            if (r,c) not in filled:
                result[r][c] = 0

    return result

