def solve_only_rows_and_cols_uniform(grid):
    """Only propagate from COMPLETELY uniform rows/cols"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    changed = True
    while changed:
        changed = False

        # Find uniform rows (single unique non-zero)
        row_vals = {}
        for r in range(n):
            nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
            if len(nz_vals) == 1:
                row_vals[r] = list(nz_vals)[0]

        # Find uniform cols
        col_vals = {}
        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                col_vals[c] = list(nz_vals)[0]

        pending = set()
        for r in range(n):
            if r in row_vals:
                for c in range(m):
                    if result[r][c] == 0:
                        pending.add((r,c))

        for c in range(m):
            if c in col_vals:
                for r in range(n):
                    if result[r][c] == 0:
                        pending.add((r,c))

        for r,c in pending:
            # All should be same since they come from uniform lines
            val = None
            if r in row_vals: val = row_vals[r]
            elif c in col_vals: val = col_vals[c]

            if val:
                result[r][c] = val
                changed = True

    return result

