def solve_with_cascade(grid):
    """Fill using cascading from ALL line types"""
    result = [row[:] for row in grid]
    n, m = len(result), len(result[0])

    diags_main = {}
    diags_anti = {}
    for r in range(n):
        for c in range(m):
            d = r - c
            s = r + c
            if d not in diags_main: diags_main[d] = []
            if s not in diags_anti: diags_anti[s] = []
            diags_main[d].append((r,c))
            diags_anti[s].append((r,c))

    changed = True
    iter_count = 0
    while changed and iter_count < 100:
        iter_count += 1

        pending_fills = set()

        for r in range(n):
            nz_vals = set(result[r][c] for c in range(m) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for c in range(m):
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        for c in range(m):
            nz_vals = set(result[r][c] for r in range(n) if result[r][c] != 0)
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r in range(n):
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        for cells in diags_main.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        for cells in diags_anti.values():
            nz_vals = {result[r][c] for r,c in cells if result[r][c] != 0}
            if len(nz_vals) == 1:
                val = list(nz_vals)[0]
                for r,c in cells:
                    if result[r][c] == 0:
                        pending_fills.add((r, c, val))

        print(f"Iter {iter_count}: {len(pending_fills)} fills, now {sum(sum(1 for v in row if v != 0) for row in result)} non-zeros")
        if len(pending_fills) <= 10:
            print(f"Pending: {pending_fills}")

        changed = False
        for r, c, val in pending_fills:
            result[r][c] = val
            changed = True

    return result

